"use strict";

// Story 10.07 — the end-of-project bilan: generated by `verify`, completed by
// the learner, checked for presence + minimum substance (never for quality).

const { test } = require("node:test");
const assert = require("node:assert");
const fs = require("fs");
const os = require("os");
const path = require("path");

const { generateBilan, bilanState, MARKER } = require("../bin/lib/bilan");
const { checkProject } = require("../bin/lib/check");
const { buildStatusReport } = require("../bin/lib/status");
const { verifyCommand } = require("../bin/lib/verify");
const { updateCommand } = require("../bin/lib/update");
const { capture, sampleProgress, tmpProject, writeFile } = require("./helpers");

function tmpHome() {
  return fs.mkdtempSync(path.join(os.tmpdir(), "ai-learn-bilan-home-"));
}

function finishedProject(statuses = ["done"]) {
  const phases = statuses.map((status, id) => ({
    id,
    name: `Phase ${id}`,
    status,
    checkpoint: 'node -e "process.exit(0)"',
    artifacts: [],
    predictionsRequired: 0,
  }));

  return tmpProject(sampleProgress({ phases }));
}

const SECTIONS = ["Encore fragile", "Erreurs marquantes", "Compromis d'architecture", "Réutilisable dans mes projets", "Recommandation"];

function completed(dir, decision = "labo") {
  let text = fs.readFileSync(path.join(dir, "docs", "bilan.md"), "utf8");

  for (const title of SECTIONS) {
    const answer = title === "Recommandation" ? `Je choisis ${decision}.` : "Réponse de l'apprenant.";
    text = text.replace(new RegExp(`(## ${title}\\n)[\\s\\S]*?(?=\\n## |$)`), `$1\n${answer}\n`);
  }

  fs.writeFileSync(path.join(dir, "docs", "bilan.md"), text);
}

function bilanErrors(dir, home) {
  return checkProject(dir, { home }).issues.errors.filter((e) => e.file === "docs/bilan.md");
}

test("last verified phase generates a prefilled bilan", () => {
  const home = tmpHome();
  const dir = finishedProject(["done", "pending"]);

  capture(() => verifyCommand({ dir, phaseId: 1, home }));

  const text = fs.readFileSync(path.join(dir, "docs", "bilan.md"), "utf8");
  assert.match(text, /Phase 0/);
  assert.match(text, /Phase 1/);
  assert.match(text, /aucune donnée/);

  for (const title of SECTIONS) {
    assert.match(text, new RegExp(`## ${title}`));
  }

  assert.strictEqual(text.split(MARKER).length - 1, 5);
});

test("a phase that is not the last never generates a bilan", () => {
  const dir = finishedProject(["pending", "pending"]);

  capture(() => verifyCommand({ dir, phaseId: 0, home: tmpHome() }));

  assert.strictEqual(fs.existsSync(path.join(dir, "docs", "bilan.md")), false);
});

test("an existing bilan is never overwritten", () => {
  const dir = finishedProject();
  writeFile(dir, "docs/bilan.md", "# mon bilan\n");

  assert.strictEqual(generateBilan({ dir, home: tmpHome() }).created, false);
  assert.strictEqual(fs.readFileSync(path.join(dir, "docs", "bilan.md"), "utf8"), "# mon bilan\n");
});

test("check flags a section still to complete", () => {
  const dir = finishedProject();
  const home = tmpHome();

  assert.ok(bilanErrors(dir, home).some((e) => /absent/.test(e.message)));

  generateBilan({ dir, home });
  const errors = bilanErrors(dir, home);

  assert.ok(errors.some((e) => /Encore fragile/.test(e.message)));

  completed(dir);
  const emptied = fs.readFileSync(path.join(dir, "docs", "bilan.md"), "utf8").replace(/(## Erreurs marquantes\n)[\s\S]*?(?=\n## )/, "$1\n");
  fs.writeFileSync(path.join(dir, "docs", "bilan.md"), emptied);

  assert.ok(bilanErrors(dir, home).some((e) => /Erreurs marquantes/.test(e.message)));
});

test("check requires exactly one valid recommendation", () => {
  const dir = finishedProject();
  const home = tmpHome();
  generateBilan({ dir, home });

  completed(dir, "labo ou abandonner");
  assert.ok(bilanErrors(dir, home).some((e) => /intégrer.*labo.*simplifier.*abandonner/.test(e.message)));

  completed(dir, "peut-être");
  assert.ok(bilanErrors(dir, home).some((e) => /Recommandation/.test(e.message)));
});

test("complete bilan passes check and shows in status", () => {
  const dir = finishedProject();
  const home = tmpHome();
  generateBilan({ dir, home });

  assert.strictEqual(bilanState(dir).state, "incomplete");
  assert.strictEqual(buildStatusReport(dir).bilan.state, "incomplete");

  completed(dir, "labo");

  assert.deepStrictEqual(bilanErrors(dir, home), []);
  assert.deepStrictEqual(bilanState(dir), { state: "complete", decision: "labo", issues: [] });
  assert.deepStrictEqual(buildStatusReport(dir).bilan, { state: "complete", decision: "labo" });
});

test("unfinished track never requires a bilan", () => {
  const dir = finishedProject(["done", "in_progress"]);

  assert.deepStrictEqual(bilanErrors(dir, tmpHome()), []);
  assert.strictEqual(buildStatusReport(dir).bilan, null);
});

test("generated content containing $ patterns is written verbatim", () => {
  const dir = tmpProject(
    sampleProgress({
      phases: [{ id: 0, name: "Coût $& et $' en $PATH", status: "done", checkpoint: 'node -e "process.exit(0)"', artifacts: [], predictionsRequired: 0 }],
    }),
  );

  generateBilan({ dir, home: tmpHome() });

  const text = fs.readFileSync(path.join(dir, "docs", "bilan.md"), "utf8");
  assert.ok(text.includes("Coût $& et $' en $PATH"));
  assert.ok(!text.includes("{{generated}}"));
});

test("update prepares the bilan of a track finished before it existed", () => {
  const dir = finishedProject();
  const home = tmpHome();

  capture(() => updateCommand({ root: dir, home }));

  assert.ok(fs.existsSync(path.join(dir, "docs", "bilan.md")));
});
